from __future__ import annotations

import argparse
import json
import os
import shutil
import subprocess
from pathlib import Path
from typing import Any

DEFAULT_WORKSPACE_ROOT = Path(
    os.environ.get(
        "HERMCLAW_AGENT_WORKSPACES",
        "/home/kiworker/hermclaw_agent_workspaces",
    )
)
EXPECTED_ORIGIN = os.environ.get(
    "HERMCLAW_AGENT_REPO",
    "git@hermclaw-gitlab:local-ai/hermclaw.git",
)

GIT_PREFIX = [
    "git",
    "-c",
    "core.autocrlf=false",
    "-c",
    "core.safecrlf=false",
]


class SalvageError(RuntimeError):
    pass


def _run(
    args: list[str],
    *,
    cwd: Path,
    check: bool = True,
) -> subprocess.CompletedProcess[str]:
    proc = subprocess.run(
        args,
        cwd=str(cwd),
        text=True,
        capture_output=True,
    )
    if check and proc.returncode != 0:
        raise SalvageError(
            f"{' '.join(args)} fehlgeschlagen: "
            f"{(proc.stderr or proc.stdout).strip()}"
        )
    return proc


def _git(
    repo: Path,
    *args: str,
    check: bool = True,
) -> str:
    return _run(
        [*GIT_PREFIX, *args],
        cwd=repo,
        check=check,
    ).stdout.strip()


def _safe_job_id(job_id: str) -> str:
    value = str(job_id).strip()
    import re

    if not re.fullmatch(
        r"[A-Za-z0-9._-]{1,200}",
        value,
    ):
        raise SalvageError("Ungültige job_id.")
    return value


def find_workspace(
    job_id: str,
    workspace_root: Path = DEFAULT_WORKSPACE_ROOT,
) -> tuple[Path, str]:
    job_id = _safe_job_id(job_id)
    root = workspace_root.resolve()
    if not root.exists() or not root.is_dir():
        raise SalvageError(
            f"Workspace-Root fehlt: {root}"
        )

    matches: list[tuple[Path, str]] = []
    for candidate in root.iterdir():
        if not candidate.is_dir():
            continue
        if not (candidate / ".git").exists():
            continue

        branch = _git(
            candidate,
            "branch",
            "--show-current",
            check=False,
        )
        if (
            branch.startswith("ai/job-")
            and job_id in branch
        ):
            matches.append(
                (
                    candidate.resolve(),
                    branch,
                )
            )

    if not matches:
        raise SalvageError(
            f"Kein isolierter Workspace für Job "
            f"{job_id} gefunden."
        )
    if len(matches) > 1:
        rendered = ", ".join(
            str(path)
            for path, _ in matches
        )
        raise SalvageError(
            "Mehrere passende Workspaces gefunden; "
            "Salvage wird aus Sicherheitsgründen "
            f"abgebrochen: {rendered}"
        )
    return matches[0]


def _dirty_paths(repo: Path) -> set[str]:
    changed = {
        line.strip()
        for line in _git(
            repo,
            "diff",
            "--name-only",
        ).splitlines()
        if line.strip()
    }
    changed.update(
        line.strip()
        for line in _git(
            repo,
            "diff",
            "--cached",
            "--name-only",
        ).splitlines()
        if line.strip()
    )
    changed.update(
        line.strip()
        for line in _git(
            repo,
            "ls-files",
            "--others",
            "--exclude-standard",
        ).splitlines()
        if line.strip()
    )
    return changed


def _restore_unexpected_worktree(
    repo: Path,
    allowed: set[str],
) -> list[str]:
    restored: list[str] = []
    for rel_path in sorted(
        _dirty_paths(repo) - allowed
    ):
        tracked = (
            _git(
                repo,
                "ls-files",
                "--error-unmatch",
                "--",
                rel_path,
                check=False,
            )
            != ""
        )
        if tracked:
            _git(
                repo,
                "restore",
                "--staged",
                "--worktree",
                "--source",
                "HEAD",
                "--",
                rel_path,
                check=False,
            )
        else:
            target = (repo / rel_path).resolve()
            try:
                target.relative_to(repo.resolve())
            except ValueError as exc:
                raise SalvageError(
                    "Pfad außerhalb des Workspace."
                ) from exc
            if target.is_dir():
                shutil.rmtree(target)
            elif target.exists():
                target.unlink()
        restored.append(rel_path)

    # Exakte Blob-Bytes herstellen; verhindert CRLF/LF-Scheinänderungen.
    _git(
        repo,
        "reset",
        "--hard",
        "HEAD",
    )
    return restored


def salvage(
    job_id: str,
    *,
    workspace_root: Path = DEFAULT_WORKSPACE_ROOT,
    expected_origin: str = EXPECTED_ORIGIN,
    handoff: dict[str, Any] | None = None,
) -> dict[str, Any]:
    repo, branch = find_workspace(
        job_id,
        workspace_root,
    )

    origin = _git(
        repo,
        "remote",
        "get-url",
        "origin",
    )
    if origin != expected_origin:
        raise SalvageError(
            "Unerwartetes Git-Origin; Salvage wird "
            f"verweigert: {origin}"
        )

    strict = bool(
        (handoff or {}).get(
            "strict_target_paths"
        )
    )
    allowed = {
        str(item)
        for item in (handoff or {}).get(
            "target_paths",
            [],
        )
    }

    restored_unexpected: list[str] = []
    if strict and allowed:
        # Vor dem Sichern nur die fachlich erlaubten Dateien behalten.
        dirty_before = _dirty_paths(repo)
        unexpected = dirty_before - allowed
        for rel_path in sorted(unexpected):
            tracked = (
                _git(
                    repo,
                    "ls-files",
                    "--error-unmatch",
                    "--",
                    rel_path,
                    check=False,
                )
                != ""
            )
            if tracked:
                _git(
                    repo,
                    "restore",
                    "--staged",
                    "--worktree",
                    "--source",
                    "HEAD",
                    "--",
                    rel_path,
                    check=False,
                )
            else:
                target = (repo / rel_path).resolve()
                try:
                    target.relative_to(
                        repo.resolve()
                    )
                except ValueError as exc:
                    raise SalvageError(
                        "Pfad außerhalb des Workspace."
                    ) from exc
                if target.is_dir():
                    shutil.rmtree(target)
                elif target.exists():
                    target.unlink()
            restored_unexpected.append(
                rel_path
            )

    head_before = _git(
        repo,
        "rev-parse",
        "HEAD",
    )

    if strict and allowed:
        for rel_path in sorted(allowed):
            _git(
                repo,
                "add",
                "-A",
                "--",
                rel_path,
                check=False,
            )
    else:
        _git(
            repo,
            "add",
            "-A",
        )

    staged = _git(
        repo,
        "diff",
        "--cached",
        "--name-only",
    )

    committed = False
    if staged:
        _run(
            [
                *GIT_PREFIX,
                "-c",
                "user.name=Hermclaw Runtime",
                "-c",
                "user.email=runtime@hermclaw.local",
                "commit",
                "-m",
                (
                    "Runtime salvage after bounded "
                    f"agent round limit ({job_id})"
                ),
            ],
            cwd=repo,
        )
        committed = True

    head_after = _git(
        repo,
        "rev-parse",
        "HEAD",
    )

    remote_head = _git(
        repo,
        "ls-remote",
        "--heads",
        "origin",
        branch,
        check=False,
    )
    already_pushed = False
    if remote_head:
        remote_sha = remote_head.split()[0]
        already_pushed = (
            remote_sha == head_after
        )

    if not already_pushed:
        _git(
            repo,
            "push",
            "-u",
            "origin",
            branch,
        )

    changed_files = [
        line.strip()
        for line in _git(
            repo,
            "diff",
            "--name-only",
            f"{head_before}...{head_after}",
        ).splitlines()
        if line.strip()
    ]

    return {
        "ok": True,
        "job_id": job_id,
        "branch": branch,
        "workspace": str(repo),
        "head": head_after,
        "salvaged": True,
        "committed_during_salvage": committed,
        "strict_target_paths": strict,
        "restored_unexpected": (
            restored_unexpected
        ),
        "changed_files": changed_files,
        "result": (
            "runtime-salvage-after-round-limit"
        ),
    }


def main() -> int:
    parser = argparse.ArgumentParser(
        description=(
            "Sichert einen fehlgeschlagenen "
            "Hermclaw-Workspace nach einem "
            "kontrollierten Rundenlimit."
        )
    )
    parser.add_argument(
        "--job-id",
        required=True,
    )
    parser.add_argument(
        "--output",
        required=True,
    )
    parser.add_argument(
        "--workspace-root",
        default=str(DEFAULT_WORKSPACE_ROOT),
    )
    parser.add_argument(
        "--expected-origin",
        default=EXPECTED_ORIGIN,
    )
    parser.add_argument(
        "--handoff",
    )
    args = parser.parse_args()

    handoff = None
    if args.handoff:
        handoff = json.loads(
            Path(args.handoff).read_text(
                encoding="utf-8"
            )
        )

    result = salvage(
        args.job_id,
        workspace_root=Path(
            args.workspace_root
        ),
        expected_origin=args.expected_origin,
        handoff=handoff,
    )
    Path(args.output).write_text(
        json.dumps(
            result,
            ensure_ascii=False,
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )

    print(
        "[SALVAGE] Kontrolliertes Rundenlimit: "
        "Workspace gesichert."
    )
    if result["restored_unexpected"]:
        print(
            "[SALVAGE] Fachfremde lokale "
            "Änderungen verworfen: "
            + ", ".join(
                result[
                    "restored_unexpected"
                ]
            )
        )
    print(
        f"[SALVAGE] branch: "
        f"{result['branch']}"
    )
    print(
        f"[SALVAGE] head: "
        f"{result['head'][:12]}"
    )
    print(
        f"[SALVAGE] Ergebnis: "
        f"{args.output}"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
